-- T11 website support: actual authenticated ownership, approved FAQ and private notes.
grant create on schema api,app_private to git_tutor_commands;
create table app_private.conversations(id uuid primary key default gen_random_uuid(),account_id uuid references app_private.accounts(id),channel text not null check(channel in('website','whatsapp')),topic text not null,source_token text,source_confidence text not null default'observed_claim',state text not null default'bot'check(state in('bot','waiting','assigned','escalated','resolved')),owner_account_id uuid references app_private.accounts(id),version integer not null default 1,bot_paused boolean not null default false,waiting_since timestamptz,last_incoming_at timestamptz,last_whatsapp_user_message_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app_private.support_messages(id uuid primary key default gen_random_uuid(),sequence bigint generated always as identity unique,conversation_id uuid not null references app_private.conversations(id),actor_account_id uuid references app_private.accounts(id),author text not null check(author in('customer','staff','bot','system')),text text not null,client_message_id uuid,created_at timestamptz not null default now(),unique(conversation_id,client_message_id));
create table app_private.support_message_delivery(message_id uuid primary key references app_private.support_messages(id),state text not null check(state in('queued','delivered','sent','read','failed','unknown','suppressed')),safe_error_code text,provider_message_id text,updated_at timestamptz not null default now());
create table app_private.support_notes(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references app_private.conversations(id),actor_account_id uuid not null references app_private.accounts(id),text text not null,created_at timestamptz not null default now());
create table app_private.support_ownership_history(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references app_private.conversations(id),actor_account_id uuid not null references app_private.accounts(id),previous_owner_id uuid references app_private.accounts(id),new_owner_id uuid references app_private.accounts(id),action text not null,private_reason text not null,created_at timestamptz not null default now());
create table app_private.approved_faq_answers(id text primary key,version integer not null,question_pattern text not null,answer text not null,approval_basis text not null,active boolean not null default true);
insert into app_private.approved_faq_answers values
('booking',1,'\m(book|booking)\M','Choose a subject and available session, then review the saved quote before accepting. Your booking confirms after the stated funding requirements are met.','synthetic_development_approved_content',true),
('formats',1,'\m(group|private|format)\M','Choose a private session or a group offer. The saved quote shows the current group size, customer tuition and confirmation conditions.','synthetic_development_approved_content',true),
('upload',1,'\m(upload|receipt|file)\M','Upload the requested file in your secure portal. A receipt is reviewed against independently verified funds; uploading it alone does not confirm payment.','synthetic_development_approved_content',true),
('payment',1,'\m(pay|payment)\M','Open your booking payment instructions for the verified collection account, amount and reference. Never send credentials in chat.','synthetic_development_approved_content',true);
create index support_queue on app_private.conversations(state,owner_account_id,waiting_since);
create index support_messages_thread on app_private.support_messages(conversation_id,sequence);
create function app_private.support_staff(p_actor uuid)returns boolean language sql stable security definer set search_path='' as $$select app_private.has_role(p_actor,'admin')or app_private.has_role(p_actor,'customer_service')$$;
create function app_private.support_read_scope(p_actor uuid,p_conversation uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from app_private.conversations c where c.id=p_conversation and(c.account_id=p_actor or app_private.support_staff(p_actor)))$$;
create function app_private.support_add_message(p_conversation uuid,p_actor uuid,p_author text,p_text text,p_client uuid default null,p_delivery text default'delivered')returns uuid language plpgsql security definer set search_path='' as $$declare id uuid:=gen_random_uuid();begin
 insert into app_private.support_messages(id,conversation_id,actor_account_id,author,text,client_message_id)values(id,p_conversation,p_actor,p_author,p_text,p_client);insert into app_private.support_message_delivery(message_id,state)values(id,p_delivery);return id;end$$;
create function app_private.support_summary(p_actor uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare c app_private.conversations%rowtype;staff boolean;window_open boolean;begin
 select * into c from app_private.conversations where id=p_id;if c.id is null then raise exception'NOT_FOUND';end if;if not app_private.support_read_scope(p_actor,c.id)then raise exception'FORBIDDEN';end if;staff:=app_private.support_staff(p_actor);window_open:=c.channel='website'or c.last_whatsapp_user_message_at>now()-interval'24 hours';
 return jsonb_build_object('conversation_id',c.id,'channel',c.channel,'topic',c.topic,'state',c.state,'version',c.version,'owner_id',case when staff then c.owner_account_id else null end,'bot_paused',c.bot_paused,'created_at',c.created_at,'waiting_since',c.waiting_since,'last_incoming_at',c.last_incoming_at,'last_whatsapp_user_message_at',c.last_whatsapp_user_message_at,'can_reply',staff and (c.owner_account_id is not distinct from p_actor) and c.state='assigned','requires_template',not coalesce(window_open,false),'can_claim',staff and c.state='waiting'and c.owner_account_id is null,'can_transfer',staff and((c.owner_account_id is not distinct from p_actor) or app_private.has_role(p_actor,'admin'))and c.state in('assigned','escalated'),'can_resolve',staff and((c.owner_account_id is not distinct from p_actor) or app_private.has_role(p_actor,'admin'))and c.state in('assigned','escalated'),'can_handoff',c.account_id=p_actor and c.state='bot','staffed_hours_configured',false);
end$$;
create function app_private.support_command(p_name text,p_input jsonb,p_key text)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor(true);c app_private.conversations%rowtype;ctx jsonb;cid uuid;prior app_private.support_messages%rowtype;answer text;note text;new_owner uuid;previous_owner uuid;begin
 if p_name='start_conversation'then
  if p_input->>'channel' is distinct from'website'or p_input->>'topic'is null or length(btrim(p_input->>'topic'))not between 1 and 200 or length(coalesce(p_input->>'source_token',''))>500 then raise exception'VALIDATION_ERROR';end if;
 else
  cid:=(p_input->>'conversation_id')::uuid;select * into c from app_private.conversations where id=cid for update;if c.id is null then raise exception'NOT_FOUND';end if;
  if p_name in('submit_message','request_handoff')then if c.account_id is distinct from actor or c.channel<>'website'then raise exception'FORBIDDEN';end if;
  else perform app_private.require_actor();if not app_private.support_staff(actor)then raise exception'FORBIDDEN';end if;
   if p_name='return_conversation'then perform app_private.require_role(actor,'admin');
   elsif p_name not in('claim_conversation','transfer_conversation','resolve_conversation')and c.owner_account_id is distinct from actor then raise exception'OWNER_REQUIRED';
   elsif p_name in('transfer_conversation','resolve_conversation')and c.owner_account_id is distinct from actor and not app_private.has_role(actor,'admin')then raise exception'OWNER_REQUIRED';end if;
  end if;
 end if;
 ctx:=app_private.booking_begin(actor,p_name,p_input,p_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if p_name not in('start_conversation','submit_message')and c.version is distinct from(p_input->>'expected_version')::integer then raise exception'VERSION_CONFLICT';end if;
 if p_name='start_conversation'then
  if(select count(*)from app_private.conversations where account_id=actor and created_at>now()-interval'1 minute')>=5 then raise exception'RATE_LIMITED';end if;
  insert into app_private.conversations(account_id,channel,topic,source_token)values(actor,'website',btrim(p_input->>'topic'),p_input->>'source_token')returning * into c;
  perform app_private.support_add_message(c.id,null,'system','You are speaking with the Git Tutor FAQ assistant. Ask to speak to a person at any time. Please keep private account and payment details in your secure portal.');
 elsif p_name='submit_message'then
  if p_input->>'text' is null or length(btrim(p_input->>'text'))not between 1 and 4000 or p_input->>'client_message_id'is null then raise exception'VALIDATION_ERROR';end if;
  select * into prior from app_private.support_messages where conversation_id=c.id and client_message_id=(p_input->>'client_message_id')::uuid;
  if prior.id is not null then if prior.actor_account_id is distinct from actor or prior.text is distinct from btrim(p_input->>'text')then raise exception'IDEMPOTENCY_CONFLICT';end if;
  else
   if(select count(*)from app_private.support_messages where actor_account_id=actor and created_at>now()-interval'1 minute')>=30 then raise exception'RATE_LIMITED';end if;
   perform app_private.support_add_message(c.id,actor,'customer',btrim(p_input->>'text'),(p_input->>'client_message_id')::uuid);
   if c.state='resolved'then c.state:='waiting';c.owner_account_id:=null;c.bot_paused:=true;c.waiting_since:=now();end if;
   if not c.bot_paused and c.state='bot'then
    if p_input->>'text'!~*'(refund|dispute|complain|human|person|account|password|personal|tutor fee|compensation|bank|مبلغ|استرداد|موظف)'then select f.answer into answer from app_private.approved_faq_answers f where f.active and p_input->>'text'~*f.question_pattern order by f.id limit 1;end if;
    if answer is null then c.state:='waiting';c.bot_paused:=true;c.waiting_since:=now();perform app_private.support_add_message(c.id,null,'system','Your request is waiting for a person. FAQ automation is paused. The team will respond when available; staffed hours have not yet been configured.');
    else perform app_private.support_add_message(c.id,null,'bot',answer);end if;
   end if;
   c.last_incoming_at:=now();c.version:=c.version+1;
  end if;
 elsif p_name='request_handoff'then
  if c.state<>'bot'then raise exception'STATE_CONFLICT';end if;if length(btrim(p_input->>'reason'))not between 1 and 2000 then raise exception'VALIDATION_ERROR';end if;c.state:='waiting';c.bot_paused:=true;c.waiting_since:=now();c.version:=c.version+1;
  perform app_private.support_add_message(c.id,actor,'customer',btrim(p_input->>'reason'));perform app_private.support_add_message(c.id,null,'system','A person will review your request when available. FAQ automation is paused.');
 elsif p_name='claim_conversation'then
  if c.state<>'waiting'or c.owner_account_id is not null then raise exception'STATE_CONFLICT';end if;new_owner:=actor;c.state:='assigned';c.bot_paused:=true;c.version:=c.version+1;note:='Claimed waiting conversation';
 elsif p_name='reply_to_conversation'then
  if c.state<>'assigned'then raise exception'STATE_CONFLICT';end if;
  if c.channel<>'website'then raise exception'TEMPLATE_REQUIRED';end if;
  if p_input->>'template_id'is not null or p_input->'template_parameters'<>'[]'::jsonb or p_input->>'text'is null or length(btrim(p_input->>'text'))not between 1 and 4000 then raise exception'VALIDATION_ERROR';end if;
  perform app_private.support_add_message(c.id,actor,'staff',btrim(p_input->>'text'));c.waiting_since:=null;c.version:=c.version+1;
 elsif p_name in('transfer_conversation','return_conversation')then
  if(p_name='transfer_conversation'and c.state not in('assigned','escalated'))or(p_name='return_conversation'and c.state<>'escalated')then raise exception'STATE_CONFLICT';end if;
  new_owner:=coalesce(p_input->>'new_owner_id',p_input->>'owner_id')::uuid;if not app_private.support_staff(new_owner)then raise exception'FORBIDDEN';end if;note:=coalesce(p_input->>'private_reason',p_input->>'private_instruction');c.state:='assigned';c.bot_paused:=true;c.version:=c.version+1;
 elsif p_name='escalate_conversation'then
  if c.state<>'assigned'then raise exception'STATE_CONFLICT';end if;note:=p_input->>'private_reason';c.state:='escalated';c.bot_paused:=true;c.version:=c.version+1;
 elsif p_name='resolve_conversation'then
  if c.state not in('assigned','escalated')then raise exception'STATE_CONFLICT';end if;if p_input->>'resolution_code'not in('answered','customer_request','duplicate','no_response')then raise exception'VALIDATION_ERROR';end if;note:=p_input->>'private_note';c.state:='resolved';c.bot_paused:=true;c.waiting_since:=null;c.version:=c.version+1;
 elsif p_name='add_conversation_note'then note:=p_input->>'private_note';c.version:=c.version+1;
 else raise exception'VALIDATION_ERROR';end if;
 if p_name in('transfer_conversation','return_conversation','escalate_conversation','resolve_conversation','add_conversation_note')then if note is null or length(btrim(note))not between 1 and 2000 then raise exception'VALIDATION_ERROR';end if;insert into app_private.support_notes(conversation_id,actor_account_id,text)values(c.id,actor,btrim(note));end if;
 if new_owner is not null then previous_owner:=c.owner_account_id;c.owner_account_id:=new_owner;insert into app_private.support_ownership_history(conversation_id,actor_account_id,previous_owner_id,new_owner_id,action,private_reason)values(c.id,actor,previous_owner,new_owner,p_name,note);end if;
 update app_private.conversations set state=c.state,owner_account_id=c.owner_account_id,bot_paused=c.bot_paused,version=c.version,waiting_since=c.waiting_since,last_incoming_at=c.last_incoming_at,updated_at=now()where id=c.id;
 return app_private.booking_finish(ctx,c.id,c.version,jsonb_build_object('conversation_id',c.id,'state',c.state,'owner_id',case when app_private.support_staff(actor)then c.owner_account_id else null end),case when p_name='claim_conversation'then'support_assigned'when p_name='return_conversation'then'support_returned'else'support_updated'end,jsonb_build_object('conversation_id',c.id,'version',c.version));
end$$;
create function api.start_conversation(p_channel text,p_topic text,p_source_token text,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('start_conversation',jsonb_build_object('channel',p_channel,'topic',p_topic,'source_token',p_source_token),p_idempotency_key)$$;
create function api.submit_message(p_conversation_id uuid,p_client_message_id uuid,p_text text,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('submit_message',jsonb_build_object('conversation_id',p_conversation_id,'client_message_id',p_client_message_id,'text',p_text),p_idempotency_key)$$;
create function api.request_handoff(p_conversation_id uuid,p_reason text,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('request_handoff',jsonb_build_object('conversation_id',p_conversation_id,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.claim_conversation(p_conversation_id uuid,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('claim_conversation',jsonb_build_object('conversation_id',p_conversation_id,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.reply_to_conversation(p_conversation_id uuid,p_text text,p_template_id uuid,p_template_parameters jsonb,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('reply_to_conversation',jsonb_build_object('conversation_id',p_conversation_id,'text',p_text,'template_id',p_template_id,'template_parameters',p_template_parameters,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.transfer_conversation(p_conversation_id uuid,p_new_owner_id uuid,p_private_reason text,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('transfer_conversation',jsonb_build_object('conversation_id',p_conversation_id,'new_owner_id',p_new_owner_id,'private_reason',p_private_reason,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.escalate_conversation(p_conversation_id uuid,p_private_reason text,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('escalate_conversation',jsonb_build_object('conversation_id',p_conversation_id,'private_reason',p_private_reason,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.return_conversation(p_conversation_id uuid,p_owner_id uuid,p_private_instruction text,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('return_conversation',jsonb_build_object('conversation_id',p_conversation_id,'owner_id',p_owner_id,'private_instruction',p_private_instruction,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.resolve_conversation(p_conversation_id uuid,p_resolution_code text,p_private_note text,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('resolve_conversation',jsonb_build_object('conversation_id',p_conversation_id,'resolution_code',p_resolution_code,'private_note',p_private_note,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.add_conversation_note(p_conversation_id uuid,p_private_note text,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.support_command('add_conversation_note',jsonb_build_object('conversation_id',p_conversation_id,'private_note',p_private_note,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.get_conversation(p_conversation_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor(true);result jsonb;messages jsonb;notes jsonb;begin
 if not exists(select 1 from app_private.conversations where id=p_conversation_id and(account_id=actor or owner_account_id=actor or app_private.has_role(actor,'admin')))then raise exception'FORBIDDEN';end if;result:=app_private.support_summary(actor,p_conversation_id);select coalesce(jsonb_agg(x.item order by x.sequence),'[]'::jsonb)into messages from(select m.sequence,jsonb_build_object('message_id',m.id,'author',m.author,'text',m.text,'created_at',m.created_at,'delivery_state',d.state)item from app_private.support_messages m join app_private.support_message_delivery d on d.message_id=m.id where m.conversation_id=p_conversation_id order by m.sequence desc limit 100)x;
 result:=result||jsonb_build_object('messages',messages,'earlier_messages_available',(select count(*)>100 from app_private.support_messages where conversation_id=p_conversation_id));
 if app_private.support_staff(actor)then select coalesce(jsonb_agg(jsonb_build_object('note_id',n.id,'text',n.text,'created_at',n.created_at)order by n.created_at,n.id),'[]'::jsonb)into notes from app_private.support_notes n where n.conversation_id=p_conversation_id;result:=result||jsonb_build_object('private_notes',notes);end if;return result;end$$;
create function app_private.support_list(p_staff boolean,p_state text,p_channel text,p_owner_id uuid,p_cursor uuid,p_limit integer)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor(true);items jsonb;begin
 if p_staff and not app_private.support_staff(actor)then raise exception'FORBIDDEN';end if;if p_limit is null or p_limit not between 1 and 100 or(p_state is not null and p_state not in('bot','waiting','assigned','escalated','resolved'))or(p_channel is not null and p_channel not in('website','whatsapp'))or(not p_staff and p_owner_id is not null)then raise exception'VALIDATION_ERROR';end if;
 if p_cursor is not null and not exists(select 1 from app_private.conversations where id=p_cursor and(p_staff or account_id=actor))then raise exception'NOT_FOUND';end if;
 select coalesce(jsonb_agg(x.item order by x.created_at desc,x.id desc),'[]'::jsonb)into items from(select c.id,c.created_at,app_private.support_summary(actor,c.id)item from app_private.conversations c where(p_staff or c.account_id=actor)and(p_state is null or c.state=p_state)and(p_channel is null or c.channel=p_channel)and(p_owner_id is null or c.owner_account_id=p_owner_id)and(p_cursor is null or(c.created_at,c.id)<(select created_at,id from app_private.conversations where id=p_cursor))order by c.created_at desc,c.id desc limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'conversation_id'else null end);end$$;
create function api.list_my_conversations(p_state text default null,p_channel text default null,p_owner_id uuid default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language sql security definer set search_path='' as $$select app_private.support_list(false,p_state,p_channel,p_owner_id,p_cursor,p_limit)$$;
create function api.list_service_conversations(p_state text default null,p_channel text default null,p_owner_id uuid default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language sql security definer set search_path='' as $$select app_private.support_list(true,p_state,p_channel,p_owner_id,p_cursor,p_limit)$$;
do $$declare t record;f record;begin
 for t in select tablename from pg_tables where schemaname='app_private'and tablename in('conversations','support_messages','support_message_delivery','support_notes','support_ownership_history','approved_faq_answers')loop
 execute format('alter table app_private.%I enable row level security',t.tablename);execute format('create policy commands_access on app_private.%I to git_tutor_commands using(true)with check(true)',t.tablename);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',t.tablename);execute format('grant select,insert on app_private.%I to git_tutor_commands',t.tablename);
 if t.tablename in('conversations','support_message_delivery')then execute format('grant update on app_private.%I to git_tutor_commands',t.tablename);else execute format('create trigger immutable_row before update or delete on app_private.%I for each row execute function app_private.reject_immutable_change()',t.tablename);end if;end loop;
 for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private')and(p.proname like'support_%'or p.proname=any(array['start_conversation','submit_message','request_handoff','claim_conversation','reply_to_conversation','transfer_conversation','escalate_conversation','return_conversation','resolve_conversation','add_conversation_note','get_conversation','list_my_conversations','list_service_conversations']))loop
 execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
grant usage on sequence app_private.support_messages_sequence_seq to git_tutor_commands;
revoke create on schema api,app_private from git_tutor_commands;
